end
function MP.ContinueOnly(state,tx)
  for _,snap in ipairs(tx.NativeWorks or {}) do
    local c=snap.Carrier;local m=c and c.MP
    if m and m.Version==2 and m.Transaction==tx.ID then MP.Advance(state,c,tx.To) end
